Here is a basic JavaScript applet that demonstrates a pendulum and allows the user to input the initial angle and release the pendulum. The applet uses the concepts of gravity, angular velocity, and friction to simulate the motion of the pendulum.

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulator</title>
    <style>
        #pendulum {
            border: 1px solid blue;
            position: relative;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 100px;
            height: 100px;
            background-color: #f0f0f0;
            padding: 10px;
            border-radius: 20px;
            text-align: center;
            font-size: 20px;
        }
    </style>
</head>
<body>
    <h1>Pendulum Simulator</h1>
    <div id="pendulum">
        <label for="initial-angle">Initial Angle:</label>
        <input type="number" id="initial-angle" value="45" min="0" max="90">
        <button id="release-button">Release</button>
    </div>

    <script>
        // constants
        const G = 9.8; // acceleration due to gravity (m/s^2)
        const J = 0.1; // moment of inertia (kg*m^2)
        const K = 0.1; // coefficient of friction (kg/m)
        const dt = 0.01; // time step (s)

        // initial conditions
        let theta = 0; // initial angle (rad)
        let omega = 0; // initial angular velocity (rad/s)
        let t = 0; // initial time (s)

        // get the initial angle from the input field
        const initialAngleInput = document.getElementById('initial-angle');
        initialAngleInput.addEventListener('input', () => {
            theta = Math.PI * initialAngleInput.value / 180;
        });

        // get the release button
        const releaseButton = document.getElementById('release-button');
        releaseButton.addEventListener('click', () => {
            releasePendulum();
        });

        // function to update the pendulum's state
        function updatePendulum() {
            // update the angular velocity
            omega += (-G * Math.sin(theta) / J - K * omega) * dt;

            // update the angle
            theta += omega * dt;

            // update the time
            t += dt;

            // check if the pendulum has stopped
            if (Math.abs(omega) < 0.01) {
                stopPendulum();
            }
        }

        // function to release the pendulum
        function releasePendulum() {
            // set the initial conditions
            theta = initialAngleInput.value * Math.PI / 180;
            omega = 0;
            t = 0;

            // update the pendulum's state
            updatePendulum();

            // interval to update the pendulum's state
            const interval = setInterval(() => {
                updatePendulum();
                // update the GUI
                document.getElementById('pendulum').innerHTML = `Time: ${t.toFixed(2)} s<br>Angle: ${theta.toFixed(2)} rad`;
            }, 10);
        }

        // function to stop the pendulum
        function stopPendulum() {
            clearInterval();
        }
    </script>
</body>
</html>
```

